using System.Text.Json;
using Dapper;
using Valora.Application.Benchmarks;
using Valora.Application.Contracts;

namespace Valora.Infrastructure.Benchmarks;

public sealed class BenchmarkComparisonRepository(IDbConnectionFactory db,IDbTransactionFactory tx):IBenchmarkCohortRepository,IBenchmarkSnapshotRepository,IBenchmarkMetricRepository,IBenchmarkComparisonRepository,IBenchmarkInsightRepository,IBenchmarkPrivacyRepository,IBenchmarkExportRepository
{
    public async Task<IReadOnlyList<BenchmarkCohortDto>> List(Guid o,CancellationToken ct){const string sql="SELECT c.id,c.name,c.description,c.segment,c.industry,c.company_size_range CompanySizeRange,c.region,c.minimum_sample_size MinimumSampleSize,c.status,count(m.id)::int MemberCount,c.updated_at UpdatedAt FROM valorapesquisa.benchmark_cohorts c LEFT JOIN valorapesquisa.benchmark_cohort_members m ON m.cohort_id=c.id AND m.deleted_at IS NULL WHERE c.organization_id=@o AND c.deleted_at IS NULL GROUP BY c.id ORDER BY c.updated_at DESC";using var c=db.Create();return(await c.QueryAsync<BenchmarkCohortDto>(new CommandDefinition(sql,new{o},cancellationToken:ct))).AsList();}
    public async Task<Guid> Create(Guid o,Guid u,CreateBenchmarkCohortRequest r,CancellationToken ct){var id=Guid.NewGuid();await using var unit=await tx.BeginAsync(ct);await unit.Connection.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_cohorts(id,organization_id,name,description,segment,industry,company_size_range,region,minimum_sample_size,status) VALUES(@id,@o,@Name,@Description,@Segment,@Industry,@CompanySizeRange,@Region,@MinimumSampleSize,'active')",new{id,o,r.Name,r.Description,r.Segment,r.Industry,r.CompanySizeRange,r.Region,r.MinimumSampleSize},unit.Transaction,cancellationToken:ct));await Audit(unit,o,u,"cohort",id,"benchmark.cohort.created","Coorte configurada sem identificação pública de membros.",ct);await unit.CommitAsync();return id;}
    async Task<IReadOnlyList<BenchmarkSnapshotDto>> IBenchmarkSnapshotRepository.List(Guid o,CancellationToken ct){const string sql="SELECT id,source_type SourceType,coalesce(source_id,survey_id,response_batch_id,result_id,id) SourceId,period_start PeriodStart,period_end PeriodEnd,maturity_score MaturityScore,confidence_level ConfidenceLevel,sample_size SampleSize,metadata_json::text MetadataJson,created_at CreatedAt FROM valorapesquisa.benchmark_snapshots WHERE organization_id=@o AND deleted_at IS NULL ORDER BY period_end DESC,created_at DESC";using var c=db.Create();return(await c.QueryAsync<BenchmarkSnapshotDto>(new CommandDefinition(sql,new{o},cancellationToken:ct))).AsList();}
    public async Task<Guid> Create(Guid o,Guid u,GenerateBenchmarkSnapshotRequest r,CancellationToken ct){var id=Guid.NewGuid();await using var unit=await tx.BeginAsync(ct);await unit.Connection.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_snapshots(id,organization_id,source_type,source_id,period_start,period_end,maturity_score,confidence_level,sample_size,metadata_json) VALUES(@id,@o,@SourceType,@SourceId,@PeriodStart,@PeriodEnd,@MaturityScore,@ConfidenceLevel,@SampleSize,CAST(@MetadataJson AS jsonb))",new{id,o,r.SourceType,r.SourceId,r.PeriodStart,r.PeriodEnd,r.MaturityScore,r.ConfidenceLevel,r.SampleSize,r.MetadataJson},unit.Transaction,cancellationToken:ct));await Audit(unit,o,u,"snapshot",id,"benchmark.snapshot.generated","Snapshot imutável gerado a partir de fonte declarada.",ct);await unit.CommitAsync();return id;}
    public async Task<Guid> CreateRequest(Guid o,Guid u,BenchmarkComparisonRequest r,CancellationToken ct){var id=Guid.NewGuid();using var c=db.Create();await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_comparison_requests(id,organization_id,comparison_type,cohort_id,segment,criterion,period_start,period_end,dimension,indicator,requested_by_user_id,status) VALUES(@id,@o,@ComparisonType,@CohortId,@Segment,@Criterion,@PeriodStart,@PeriodEnd,@Dimension,@Indicator,@u,'processing')",new{id,o,u,r.ComparisonType,r.CohortId,r.Segment,r.Criterion,r.PeriodStart,r.PeriodEnd,r.Dimension,r.Indicator},cancellationToken:ct));return id;}
    public async Task<IReadOnlyList<BenchmarkMetricDto>> Compare(Guid o,Guid requestId,BenchmarkComparisonRequest r,CancellationToken ct){const string sql="""
SELECT 'maturity' MetricKey,'Maturidade' MetricName,NULL::text Dimension,max(s.maturity_score) FILTER(WHERE s.organization_id=@o) OrganizationValue,
 CASE WHEN @ComparisonType='history' THEN min(s.maturity_score) ELSE avg(s.maturity_score) FILTER(WHERE s.organization_id<>@o) END BenchmarkValue,
 max(s.maturity_score) FILTER(WHERE s.organization_id=@o)-(CASE WHEN @ComparisonType='history' THEN min(s.maturity_score) ELSE avg(s.maturity_score) FILTER(WHERE s.organization_id<>@o) END) Difference,
 CASE WHEN count(*)>=5 THEN percent_rank() OVER(ORDER BY max(s.maturity_score) FILTER(WHERE s.organization_id=@o))*100 ELSE NULL END Percentile,
 CASE WHEN min(s.confidence_level)='high' THEN 'high' ELSE 'medium' END ConfidenceLevel,sum(s.sample_size)::int SampleSize,'aggregated' DataKind
FROM valorapesquisa.benchmark_snapshots s LEFT JOIN valorapesquisa.benchmark_cohort_members cm ON cm.member_organization_id=s.organization_id AND cm.cohort_id=@CohortId AND cm.deleted_at IS NULL
WHERE s.deleted_at IS NULL AND s.period_start>=@PeriodStart AND s.period_end<=@PeriodEnd AND (@ComparisonType='history' AND s.organization_id=@o OR @ComparisonType='units' AND s.organization_id=@o OR @ComparisonType='cohort' AND (s.organization_id=@o OR cm.id IS NOT NULL))
HAVING count(*)>0
""";using var c=db.Create();return(await c.QueryAsync<BenchmarkMetricDto>(new CommandDefinition(sql,new{o,requestId,r.ComparisonType,r.CohortId,r.PeriodStart,r.PeriodEnd},cancellationToken:ct))).AsList();}
    public async Task Complete(Guid o,Guid id,bool available,string confidence,int sampleSize,IReadOnlyList<string> limitations,CancellationToken ct){using var c=db.Create();await c.ExecuteAsync(new CommandDefinition("UPDATE valorapesquisa.benchmark_comparison_requests SET status='completed',updated_at=now() WHERE id=@id AND organization_id=@o; INSERT INTO valorapesquisa.benchmark_comparison_results(organization_id,comparison_request_id,is_available,confidence_level,sample_size,limitations_json) VALUES(@o,@id,@available,@confidence,@sampleSize,CAST(@limitations AS jsonb))",new{o,id,available,confidence,sampleSize,limitations=JsonSerializer.Serialize(limitations)},cancellationToken:ct));}
    public async Task<BenchmarkComparisonDto?> Get(Guid o,Guid id,CancellationToken ct){const string sql="SELECT r.id,r.comparison_type ComparisonType,r.segment,r.criterion,r.period_start PeriodStart,r.period_end PeriodEnd,x.is_available IsAvailable,x.confidence_level ConfidenceLevel,x.sample_size SampleSize,x.limitations_json::text LimitationsJson FROM valorapesquisa.benchmark_comparison_requests r JOIN valorapesquisa.benchmark_comparison_results x ON x.comparison_request_id=r.id WHERE r.id=@id AND r.organization_id=@o";using var c=db.Create();var row=await c.QuerySingleOrDefaultAsync<ComparisonRow>(new CommandDefinition(sql,new{o,id},cancellationToken:ct));if(row is null)return null;var req=new BenchmarkComparisonRequest{ComparisonType=row.ComparisonType,Segment=row.Segment,Criterion=row.Criterion,PeriodStart=row.PeriodStart,PeriodEnd=row.PeriodEnd};var values=row.IsAvailable?await Compare(o,id,req,ct):[];return new(row.Id,row.ComparisonType,row.Segment,row.Criterion,row.PeriodStart,row.PeriodEnd,row.IsAvailable,row.ConfidenceLevel,row.SampleSize,JsonSerializer.Deserialize<string[]>(row.LimitationsJson)??[],values);}
    public async Task<IReadOnlyList<BenchmarkInsightDto>> ListInsights(Guid o,CancellationToken ct)=>await ((IBenchmarkInsightRepository)this).List(o,ct);
    async Task<IReadOnlyList<BenchmarkInsightDto>> IBenchmarkInsightRepository.List(Guid o,CancellationToken ct){const string sql="SELECT id,insight_type InsightType,title,description,evidence_summary EvidenceSummary,confidence_level ConfidenceLevel,status,action_id ActionId,created_at CreatedAt FROM valorapesquisa.benchmark_insights WHERE organization_id=@o AND deleted_at IS NULL ORDER BY created_at DESC";using var c=db.Create();return(await c.QueryAsync<BenchmarkInsightDto>(new CommandDefinition(sql,new{o},cancellationToken:ct))).AsList();}
    public async Task<Guid> ConvertToAction(Guid o,Guid insightId,Guid u,CancellationToken ct){var action=Guid.NewGuid();var plan=Guid.NewGuid();await using var unit=await tx.BeginAsync(ct);var changed=await unit.Connection.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.action_plans(id,organization_id,title,status) SELECT @plan,@o,'Ações de benchmark','open' WHERE EXISTS(SELECT 1 FROM valorapesquisa.benchmark_insights WHERE id=@insightId AND organization_id=@o AND status='open' AND deleted_at IS NULL); INSERT INTO valorapesquisa.action_items(id,organization_id,action_plan_id,title,description,origin_type,origin_id,priority,status,evidence_summary,expected_outcome) SELECT @action,@o,@plan,title,description,'benchmark',id,'medium','pending',evidence_summary,'Melhoria validada pela liderança' FROM valorapesquisa.benchmark_insights WHERE id=@insightId AND organization_id=@o AND status='open' AND deleted_at IS NULL; UPDATE valorapesquisa.benchmark_insights SET status='converted',action_id=@action,updated_at=now() WHERE id=@insightId AND organization_id=@o AND status='open'",new{o,u,insightId,action,plan},unit.Transaction,cancellationToken:ct));if(changed==0)throw new InvalidOperationException("Insight indisponível para conversão.");await Audit(unit,o,u,"insight",insightId,"benchmark.insight.converted_to_action","Conversão solicitada e preservada como decisão humana.",ct);await unit.CommitAsync();return action;}
    public async Task<BenchmarkPrivacyRuleDto> Get(Guid o,CancellationToken ct){const string sql="SELECT id,minimum_sample_size MinimumSampleSize,k_anonymity KAnonymity,status,suppression_reason SuppressionReason,updated_at UpdatedAt FROM valorapesquisa.benchmark_privacy_rules WHERE organization_id=@o AND status='active' AND deleted_at IS NULL ORDER BY updated_at DESC LIMIT 1";using var c=db.Create();var rule=await c.QuerySingleOrDefaultAsync<BenchmarkPrivacyRuleDto>(new CommandDefinition(sql,new{o},cancellationToken:ct));return rule??new(Guid.Empty,5,5,"active",null,DateTimeOffset.UtcNow);}
    public async Task AuditBlocked(Guid o,Guid u,string reason,CancellationToken ct){using var c=db.Create();await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_audit_events(organization_id,entity_type,entity_id,event_type,performed_by_user_id,summary) VALUES(@o,'privacy',@id,'benchmark.privacy.blocked',@u,@reason)",new{o,u,reason,id=Guid.NewGuid()},cancellationToken:ct));}
    public async Task<Guid> Create(Guid o,Guid u,BenchmarkExportRequest r,CancellationToken ct){var id=Guid.NewGuid();using var c=db.Create();var changed=await c.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_exports(id,organization_id,snapshot_id,comparison_request_id,format,status,requested_by_user_id) SELECT @id,@o,(SELECT id FROM valorapesquisa.benchmark_snapshots WHERE organization_id=@o AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 1),@ComparisonId,@Format,'requested',@u WHERE EXISTS(SELECT 1 FROM valorapesquisa.benchmark_comparison_results x JOIN valorapesquisa.benchmark_comparison_requests q ON q.id=x.comparison_request_id WHERE q.id=@ComparisonId AND q.organization_id=@o AND x.is_available)",new{id,o,u,r.ComparisonId,r.Format},cancellationToken:ct));if(changed==0)throw new InvalidOperationException("Somente comparações disponíveis podem ser exportadas.");return id;}
    private static Task Audit(IUnitOfWork unit,Guid o,Guid u,string type,Guid id,string eventName,string summary,CancellationToken ct)=>unit.Connection.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.benchmark_audit_events(organization_id,entity_type,entity_id,event_type,performed_by_user_id,summary) VALUES(@o,@type,@id,@eventName,@u,@summary)",new{o,u,type,id,eventName,summary},unit.Transaction,cancellationToken:ct));
    private sealed record ComparisonRow(Guid Id,string ComparisonType,string Segment,string Criterion,DateOnly PeriodStart,DateOnly PeriodEnd,bool IsAvailable,string ConfidenceLevel,int SampleSize,string LimitationsJson);
}
